def camel_to_snake(s: str) -> str:
    out = []
    for i, ch in enumerate(s):
        if "A" <= ch <= "Z":
            if i == 0:
                out.append(ch.lower())
            else:
                out.append("_" + ch.lower())
        else:
            out.append(ch)
    return "".join(out)
